func checkNetmapConfExists() (NetworkNameMapper, error) {
	pathNetmap := workstationNetmapConfPath()

	// Check if the default network mapper configuration file exists.
	if _, err := os.Stat(pathNetmap); err == nil {
		// If the default network mapper configuration file exists, read the configuration.
		log.Printf("Located the network mapper configuration file: %s", pathNetmap)
		return ReadNetmapConfig(pathNetmap)
	} else if !errors.Is(err, os.ErrNotExist) {
		// There was an error other than the file not existing.
		return nil, fmt.Errorf("error checking default network mapper configuration: %w", err)
	}

	log.Printf("A network mapper configuration file does not exist in the default path: %s", pathNetmap)

	// The file does not exist, check the alternate configuration path.
	libpath, _ := workstationVMwareRoot()
	pathNetworking := filepath.Join(libpath, "networking")
	log.Printf("Checking alternate path for network mapper configuration file: %s", pathNetworking)

	_, err := os.Stat(pathNetworking)
	if err == nil {
		// Alternate networking configuration path exists. Using this path.
		log.Printf("Located the network mapper configuration file: %s", pathNetworking)
		fd, err := os.Open(pathNetworking)
		if err != nil {
			return nil, err
		}
		defer fd.Close()

		// Then we pass the handle to the networking configuration parser.
		return ReadNetworkingConfig(fd)
	}

	if runtime.GOOS == "windows" && errors.Is(err, os.ErrNotExist) {
		// Neither the default nor alternate exists.
		// Generate the network mapper configuration file in the default path.
		log.Printf("Generating a network mapper configuration file in the default path: %s", pathNetmap)
		pathNetmap, err := generateNetmapConfig()
		if err != nil {
			log.Fatalf("error generating the absent network configuration file: %v", err)
			return nil, err
		}
		// If the file exists, attempt to read the newly generated
		// network mapper configuration file.
		return ReadNetmapConfig(pathNetmap)
	}

	if !errors.Is(err, os.ErrNotExist) {
		return nil, fmt.Errorf("error checking alternate network mapper configuration: %w", err)
	}

	// For non-Windows, if neither the default nor alternate
	// configuration paths exist, return an error.
	return nil, fmt.Errorf("error determining network mappings from files in path: %s", libpath)
}

